# ── Import function ──────────────────────────────────────────────────────────────


def import_purchase_orders() -> None:
    po_created = po_skipped = detail_created = detail_skipped = detail_no_sku = 0

    sku_to_variant = {v.sku_variant_code: v for v in ProductVariant.objects.filter(company_id=COMPANY_ID)}
    print(f"Loaded {len(sku_to_variant)} variants from DB")

    with transaction.atomic():
        for rec in PO_RECORDS:
            _, created = PurchaseOrder.objects.get_or_create(
                id=rec["id"],
                defaults={
                    "company_id": COMPANY_ID,
                    "warehouse_id": WAREHOUSE_ID,
                    **{k: v for k, v in rec.items() if k != "id"},
                },
            )
            if created:
                po_created += 1
            else:
                po_skipped += 1

        for rec in DETAIL_RECORDS:
            sql_ulid = rec["product_variant_id"]
            sku = VARIANT_ULID_TO_SKU.get(sql_ulid)
            if not sku:
                print(f"  WARNING: no SKU mapping for ULID {sql_ulid}, skipping")
                detail_no_sku += 1
                continue
            variant = sku_to_variant.get(sku)
            if not variant:
                print(f"  INFO: SKU {sku} not in this company's DB, skipping")
                detail_no_sku += 1
                continue

            _, created = PurchaseOrderDetail.objects.get_or_create(
                id=rec["id"],
                defaults={
                    "company_id": COMPANY_ID,
                    "product_variant": variant,
                    **{k: v for k, v in rec.items() if k not in ("id", "product_variant_id")},
                },
            )
            if created:
                detail_created += 1
            else:
                detail_skipped += 1

    print(f"POs:     created={po_created}, skipped={po_skipped}")
    print(f"Details: created={detail_created}, skipped={detail_skipped}, no_variant={detail_no_sku}")

if __name__ == "__main__":
    import_purchase_orders()
